+			b.Change(nodeChange)
+
+			out := &nodeOutput{}
+			out.Body.Node = nodeFromView(node)
+
+			return out, nil
+		case customExpiry != nil:
+			expiry = *customExpiry
+		}
+
+		node, nodeChange, err := b.State.SetNodeExpiry(nodeID, &expiry)
+		if err != nil {
+			return nil, mapError("expiring node", err)
+		}
+
+		b.Change(nodeChange)
+
+		out := &nodeOutput{}
+		out.Body.Node = nodeFromView(node)
