+		nodeID, err := parseNodeID(in.NodeID)
+		if err != nil {
+			return nil, err
+		}
+
+		// Tagged nodes must keep at least one tag, so reject an empty set
+		// before touching state, as gRPC does.
+		if len(in.Body.Tags) == 0 {
+			return nil, huma.Error400BadRequest(
